// Define the lease agreement as a class
data class Lease(
    val leaseStart: LocalDate,
    val leaseEnd: LocalDate,
    val rent: Double,
    val utilities: List<String>,
    val restrictions: List<String>
)

// Define a function to read the lease agreement
