leaseStart: ${lease.leaseStart}
leaseEnd: ${lease.leaseEnd}
rent: ${lease.rent}
utilities: ${lease.utilities.joinToString(", ")}
restrictions: ${lease.restrictions.joinToString(", ")}
""".trimMargin()

